impl Document {
    pub(crate) fn compare_mode_declaration(
        &self,
        other: &Document,
        a: &ModeDeclaration,
        b: &ModeDeclaration,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_structure_element(other, a.base(), b.base(), path)?;
        self.compare_atp_blueprintable(other, a.atp_blueprintable(), b.atp_blueprintable(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_value() != b.get_value() {
            return Err(format!("{path}: VALUE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mode_declaration_group(
        &self,
        other: &Document,
        a: &ModeDeclarationGroup,
        b: &ModeDeclarationGroup,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_type(other, a.base(), b.base(), path)?;
        if a.get_initial_mode_ref() != b.get_initial_mode_ref() {
            return Err(format!("{path}: INITIAL_MODE_REF mismatch"));
        }
        let list_a = a.get_mode_declarations();
        let list_b = b.get_mode_declarations();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MODE_DECLARATIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.mode_declarations.get(*x).ok_or_else(|| {
                format!("{path}.MODE_DECLARATIONS[{index}]: id not found in own arena")
            })?;
            let y = other.mode_declarations.get(*y).ok_or_else(|| {
                format!("{path}.MODE_DECLARATIONS[{index}]: id not found in other arena")
            })?;
            self.compare_mode_declaration(
                other,
                x,
                y,
                &format!("{path}.MODE_DECLARATIONS[{index}]"),
            )?;
        }
        if a.get_mode_manager_error_behavior() != b.get_mode_manager_error_behavior() {
            return Err(format!("{path}: MODE_MANAGER_ERROR_BEHAVIOR mismatch"));
        }
        let list_a = a.get_mode_transitions();
        let list_b = b.get_mode_transitions();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MODE_TRANSITIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.mode_transitions.get(*x).ok_or_else(|| {
                format!("{path}.MODE_TRANSITIONS[{index}]: id not found in own arena")
            })?;
            let y = other.mode_transitions.get(*y).ok_or_else(|| {
                format!("{path}.MODE_TRANSITIONS[{index}]: id not found in other arena")
            })?;
            self.compare_mode_transition(
                other,
                x,
                y,
                &format!("{path}.MODE_TRANSITIONS[{index}]"),
            )?;
        }
        if a.get_mode_user_error_behavior() != b.get_mode_user_error_behavior() {
            return Err(format!("{path}: MODE_USER_ERROR_BEHAVIOR mismatch"));
        }
        if a.get_on_transition_value() != b.get_on_transition_value() {
            return Err(format!("{path}: ON_TRANSITION_VALUE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mode_declaration_group_prototype(
        &self,
        other: &Document,
        a: &ModeDeclarationGroupPrototype,
        b: &ModeDeclarationGroupPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_prototype(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_sw_calibration_access() != b.get_sw_calibration_access() {
            return Err(format!("{path}: SW_CALIBRATION_ACCESS mismatch"));
        }
        if a.get_type_t_ref() != b.get_type_t_ref() {
            return Err(format!("{path}: TYPE_T_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mode_declaration_group_prototype_mapping(
        &self,
        _other: &Document,
        a: &ModeDeclarationGroupPrototypeMapping,
        b: &ModeDeclarationGroupPrototypeMapping,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_first_mode_group_ref() != b.get_first_mode_group_ref() {
            return Err(format!("{path}: FIRST_MODE_GROUP_REF mismatch"));
        }
        if a.get_mode_declaration_mapping_set_ref() != b.get_mode_declaration_mapping_set_ref() {
            return Err(format!("{path}: MODE_DECLARATION_MAPPING_SET_REF mismatch"));
        }
        if a.get_second_mode_group_ref() != b.get_second_mode_group_ref() {
            return Err(format!("{path}: SECOND_MODE_GROUP_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mode_error_behavior(
        &self,
        _other: &Document,
        a: &ModeErrorBehavior,
        b: &ModeErrorBehavior,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_default_mode_ref() != b.get_default_mode_ref() {
            return Err(format!("{path}: DEFAULT_MODE_REF mismatch"));
        }
        if a.get_error_reaction_policy() != b.get_error_reaction_policy() {
            return Err(format!("{path}: ERROR_REACTION_POLICY mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mode_request_type_map(
        &self,
        _other: &Document,
        a: &ModeRequestTypeMap,
        b: &ModeRequestTypeMap,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_implementation_data_type_ref() != b.get_implementation_data_type_ref() {
            return Err(format!("{path}: IMPLEMENTATION_DATA_TYPE_REF mismatch"));
        }
        if a.get_mode_group_ref() != b.get_mode_group_ref() {
            return Err(format!("{path}: MODE_GROUP_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mode_transition(
        &self,
        other: &Document,
        a: &ModeTransition,
        b: &ModeTransition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_structure_element(other, a.base(), b.base(), path)?;
        if a.get_entered_mode_ref() != b.get_entered_mode_ref() {
            return Err(format!("{path}: ENTERED_MODE_REF mismatch"));
        }
        if a.get_exited_mode_ref() != b.get_exited_mode_ref() {
            return Err(format!("{path}: EXITED_MODE_REF mismatch"));
        }
        Ok(())
    }
}
